    lasso: ["fit_lasso", v =&gt; `, lambda = ${f(v)}`, v =&gt; `, lam=${f(v)}`],
    "elastic net": ["fit_enet", v =&gt; `, lambda = ${f(v)}`, v =&gt; `, lam=${f(v)}`],
    "best subset": ["fit_subset", v =&gt; `, k = ${f(v)}`, v =&gt; `, k=${f(v)}`],
    backward: ["fit_subset", v =&gt; `, k = ${f(v)}, method = "backward"`, v =&gt; `, k=${f(v)}, method="backward"`],
    STLSQ: ["fit_stlsq", v =&gt; `, threshold = ${f(v)}`, v =&gt; `, threshold=${f(v)}`]
  }[method];
  const v = spec.values[step];
