  const pyExtra = extras.length ? `
extra = extra_terms(${W}, {${extras.map(e =&gt; `"${e.name}": "${e.expr}"`).join(",\n                         ")}})
Theta = bind_terms(Theta, extra)` : "";
  if (!single) return {
    r: `${rLoad}drivers &lt;- ${rDrivers}
drv &lt;- make_drivers(${W}, drivers)
Theta &lt;- make_library(drv, degree = ${degree}, pairs = ${P})${rExtra}
${rTrs}
fit &lt;- function(X, dy) ${call[0]}(X, dy${rArgs})

d &lt;- make_design_states(Theta, trs, "${genotype}", drivers, ${degree}, ${P}, ${F})
